import os
import psutil
from typing import Dict, List, Any, Optional

from .config import (
    CRITICAL_SYSTEM_PROCESSES, TYPOSQUAT_PATTERNS, SUSPICIOUS_PATHS,
    SCORE_CRITICAL, SCORE_HIGH, SCORE_MEDIUM, SCORE_LOW
)
